calc:
/* Capital nominal vs réel dans le temps : réel = nominal / (1+inflation)^t */
(function () {
  var svg = document.getElementById("mo-chart");
  if (!svg) return;
  function v(id){ return parseFloat(document.getElementById(id).value); }
  function setT(id,t){ var e=document.getElementById(id); if(e) e.textContent=t; }
  function al(){ return document.body.getAttribute("data-active-lang")||"fr"; }

  function draw(){
    var r=v("mo-r")/100, inf=v("mo-i")/100, Th=v("mo-t");
    setT("mo-r-o",(r*100).toFixed(2)+"%"); setT("mo-i-o",(inf*100).toFixed(2)+"%"); setT("mo-t-o",Th.toFixed(0));
    var rr = (1+r)/(1+inf)-1;
    setT("mo-rr",(rr*100).toFixed(2)+"%");
    var finalReal = 100*Math.pow(1+rr,Th);
    setT("mo-final", finalReal.toFixed(1));

    var W=520,H=260,L=46,R=14,T=16,B=32, pw=W-L-R, ph=H-T-B;
    var base=100;
    var nomEnd = base*Math.pow(1+r,Th);
    var realEnd = base*Math.pow(1+rr,Th);
    var ymax = Math.max(nomEnd, base)*1.08;
    var ymin = Math.min(realEnd, base)*0.92;
    if (ymax-ymin<1){ ymax=base*1.1; ymin=base*0.9; }
    function px(t){ return L + t/Th*pw; }
    function py(y){ return T + (1-(y-ymin)/(ymax-ymin))*ph; }

    var g2="";
    g2+='<line class="axis" x1="'+L+'" y1="'+T+'" x2="'+L+'" y2="'+(T+ph)+'"/>';
    g2+='<line class="axis" x1="'+L+'" y1="'+(T+ph)+'" x2="'+(L+pw)+'" y2="'+(T+ph)+'"/>';
    // ligne base 100
    g2+='<line x1="'+L+'" y1="'+py(base).toFixed(1)+'" x2="'+(L+pw)+'" y2="'+py(base).toFixed(1)+'" stroke="var(--ink-mute)" stroke-width="1" stroke-dasharray="4 3"/>';
    g2+='<text class="tick" x="'+(L+pw)+'" y="'+(py(base)-4).toFixed(1)+'" text-anchor="end">100</text>';
    // courbes nominale et réelle
    var N=100, dn="", dr="";
    for (var i=0;i<=N;i++){
      var tt=Th*i/N;
      var yn=base*Math.pow(1+r,tt);
      var yr=base*Math.pow(1+rr,tt);
      dn += (dn===""?"M ":" L ")+px(tt).toFixed(1)+","+py(yn).toFixed(1);
      dr += (dr===""?"M ":" L ")+px(tt).toFixed(1)+","+py(yr).toFixed(1);
    }
    g2+='<path d="'+dn+'" fill="none" stroke="var(--teal)" stroke-width="2.6"/>';
    g2+='<path d="'+dr+'" fill="none" stroke="var(--crimson)" stroke-width="2.6"/>';
    // points finaux
    g2+='<circle cx="'+px(Th).toFixed(1)+'" cy="'+py(nomEnd).toFixed(1)+'" r="3.5" fill="var(--teal)"/>';
    g2+='<circle cx="'+px(Th).toFixed(1)+'" cy="'+py(realEnd).toFixed(1)+'" r="3.5" fill="var(--crimson)"/>';
    // ticks x
    g2+='<text class="tick" x="'+L+'" y="'+(H-16)+'" text-anchor="start">0</text>';
    g2+='<text class="tick" x="'+(L+pw)+'" y="'+(H-16)+'" text-anchor="end">'+Th.toFixed(0)+' '+(al()==="en"?"yr":(al()==="nl"?"jr":"ans"))+'</text>';
    // ticks y
    g2+='<text class="tick" x="'+(L-6)+'" y="'+(py(ymax)+4).toFixed(1)+'" text-anchor="end">'+ymax.toFixed(0)+'</text>';
    g2+='<text class="tick" x="'+(L-6)+'" y="'+(py(ymin)+0).toFixed(1)+'" text-anchor="end">'+ymin.toFixed(0)+'</text>';
    var xlab = al()==="en"?"years":(al()==="nl"?"jaren":"années");
    var ylab = al()==="en"?"capital (base 100)":(al()==="nl"?"kapitaal (basis 100)":"capital (base 100)");
    g2+='<text class="lab" x="'+(L+pw/2)+'" y="'+(H-3)+'" text-anchor="middle">'+xlab+'</text>';
    g2+='<text class="lab" x="'+(L-36)+'" y="'+(T+ph/2)+'" text-anchor="middle" transform="rotate(-90 '+(L-36)+' '+(T+ph/2)+')">'+ylab+'</text>';
    svg.innerHTML=g2;
  }

  ["mo-r","mo-i","mo-t"].forEach(function(id){ var e=document.getElementById(id); if(e) e.addEventListener("input", draw); });
  document.querySelectorAll("[data-set-lang]").forEach(function(b){ b.addEventListener("click", function(){ setTimeout(draw,10); }); });
  document.addEventListener("DOMContentLoaded", draw);
  draw();
})();
